        panel.querySelector('#armature-debug-movement-file')?.addEventListener('change', async event => {
            const file = event.target.files?.[0]; event.target.value = '';
            if (!file) return;
            try {
                if (file.size > 1024 * 1024) throw new Error('Movement JSON must be no larger than 1 MB.');
                const text = (await file.text()).replace(/^\uFEFF/, '');
                const live = this._currentArmature;
                if (!live?.root || this.objects.getObjectById(live.root.id) !== live.root) throw new Error('Select a character first.');
                const move = this._validateImportedDebuggerMovement(text, live);
                this._openArmatureMovementDebugger(live, move.key, { movementEntry: move, prepared: true });
            } catch (error) { Utils.showToast(error.message || 'Movement import failed.', 'error'); }
        });

