        panel.querySelectorAll('.armature-move-btn').forEach(btn => {
            btn.addEventListener('click', () => {
                const liveArmature = getLivePanelArmature();
                const livePoseCatalog = this._getActiveArmaturePoseCatalog(liveArmature);
                const key = btn.dataset.moveKey;
                syncSelectedMovementTempo(key);
                const moveCatalog = this._getActiveArmatureMovementCatalog(liveArmature) || {};
                const resolvedMove = this._resolveFront3qTurnAroundMovementAlias?.(liveArmature, key, moveCatalog) || { key, entry: moveCatalog[key] };
                const activeMoveKey = resolvedMove.key || key;
                const eligibleMove = resolvedMove.entry || moveCatalog[activeMoveKey];
                if (eligibleMove && !this._armatureMovementMatchesCurrentView(liveArmature, { ...eligibleMove, key: activeMoveKey })) {
                    Utils.showToast('That movement belongs to another character view. The catalog has been refreshed.', 'warning');
                    this._buildArmaturePanel(liveArmature, { preserveState: true, reuseExisting: true });
                    return;
                }
                markArmatureActionRecent(armatureActionId('movement', key));
                const playingKey = this._getArmaturePlayingKey(liveArmature);
                if (playingKey === key || playingKey === activeMoveKey) {
                    this._stopArmatureMovement(liveArmature);
                    if (!this._armatureLayerMode) {
                        this._captureArmatureStageBasePosition(liveArmature);
                        this._applyArmaturePose(liveArmature, livePoseCatalog['idle'] || { jointAngles: {} });
                    }
                    this._storeUniversalCharacterFamilyState(liveArmature, { type: 'idle', key: null });
                } else {
                    this._stopArmatureMovement(liveArmature);
                    this._captureArmatureStageBasePosition(liveArmature);
                    const moveEntry = resolvedMove.entry || moveCatalog[activeMoveKey];
                    const isTurnAround = moveEntry?.turnAround === true;
                    const isFrontBackTurnAround = moveEntry?.frontBackTurnAround === true;
                    const isFlipInPlace = moveEntry?.flipInPlace === true;
                    if (shouldRecordArmatureAction()) {
                        excludeArmatureFromContinuousSampler(liveArmature);
                        if (isFlipInPlace) {
                            this._recordArmatureFlipInPlace(liveArmature, activeMoveKey, getArmatureContinuousRecordOptions());
                        } else if (isFrontBackTurnAround) {
                            this._recordArmatureFrontBackTurnAroundMovement(liveArmature, activeMoveKey, getArmatureContinuousRecordOptions());
                        } else if (isTurnAround) {
                            this._recordArmatureTurnAroundMovement(liveArmature, activeMoveKey, getArmatureContinuousRecordOptions());
                        } else {
                            this._recordArmatureMovementWithEndFacing(liveArmature, activeMoveKey, {
                                ...getArmatureContinuousRecordOptions(),
                                endFacingKey: this._armatureEndFacingKey,
                                endFacingTurnMode: this._armatureEndFacingTurnMode,
                                endFacingTurnSide: this._armatureEndFacingTurnSide,
                                finishPoseKey: this._armatureFinishPoseKey,
                                finishExpressionKey: this._armatureFinishExpressionKey,
                                finishGazeKey: this._armatureFinishGazeKey,
                                previewAfterRecord: !isMainTimelineContinuousRecordingEnabled()
                            });
                        }
                    } else if (isFlipInPlace) {
                        this._playArmatureFlipInPlace(liveArmature, activeMoveKey);
                    } else if (isFrontBackTurnAround) {
                        this._playArmatureFrontBackTurnAroundMovement(liveArmature, activeMoveKey);
                        this._storeUniversalCharacterFamilyState(liveArmature, { type: 'movement', key: activeMoveKey });
                    } else if (isTurnAround) {
                        this._playArmatureTurnAroundMovement(liveArmature, activeMoveKey);
                        this._storeUniversalCharacterFamilyState(liveArmature, { type: 'movement', key: activeMoveKey });
                    } else {
                        this._playArmatureMovementWithEndFacing(liveArmature, activeMoveKey, {
                            endFacingKey: this._armatureEndFacingKey,
                            endFacingTurnMode: this._armatureEndFacingTurnMode,
                            endFacingTurnSide: this._armatureEndFacingTurnSide,
                            finishPoseKey: this._armatureFinishPoseKey,
                            finishExpressionKey: this._armatureFinishExpressionKey,
                            finishGazeKey: this._armatureFinishGazeKey
                        });
                        this._storeUniversalCharacterFamilyState(liveArmature, { type: 'movement', key: activeMoveKey });
                    }
                }
                eventBus.emit('history:push');
                this._updateArmaturePanelPlayState();
            });
        });

